
<?php

session_start();

// Require login.
if (!isset($_SESSION['user_id'])) {
    header('Location: login.php');
    exit;
}

// Get the translated file ID stored after successful translation.
$fileId = $_SESSION['translated_document'] ?? '';

// Only allow the random hexadecimal IDs generated by process_document.php.
if (!is_string($fileId) || !preg_match('/^[a-f0-9]{32}$/', $fileId)) {
    http_response_code(404);
    exit('No translated document is available for download.');
}

// Build the file path safely.
$filePath = __DIR__ . '/storage/translations/' . $fileId . '.txt';

if (!is_file($filePath) || !is_readable($filePath)) {
    http_response_code(404);
    exit('The translated document could not be found.');
}

// Use the original filename saved in the session.
$downloadName = $_SESSION['translated_document_name']
    ?? 'translated_document.txt';

// Remove characters that could interfere with the download filename.
$downloadName = basename(str_replace('\\', '/', $downloadName));
$downloadName = preg_replace('/[^A-Za-z0-9._-]/', '_', $downloadName);

if ($downloadName === '' || $downloadName === '.txt') {
    $downloadName = 'translated_document.txt';
}

header('Content-Type: text/plain; charset=UTF-8');
header('Content-Disposition: attachment; filename="' . $downloadName . '"');
header('Content-Length: ' . filesize($filePath));
header('X-Content-Type-Options: nosniff');
header('Cache-Control: private, no-store');

readfile($filePath);
exit;
